pub static DORIS_BRACKET_PAIRS: LazyLock<BracketPairSet> = LazyLock::new(|| { BracketPairSet(vec![
    BracketPairEntry { open: "{", close: "}", start_type: "start_curly_bracket", end_type: "end_curly_bracket", persists: false },
    BracketPairEntry { open: "(", close: ")", start_type: "start_bracket", end_type: "end_bracket", persists: true },
    BracketPairEntry { open: "[", close: "]", start_type: "start_square_bracket", end_type: "end_square_bracket", persists: false },
]) });

pub static DORIS_CLIENT_COMMANDS: Option<sqlfluffrs_types::ClientCommandRules> = Some(sqlfluffrs_types::ClientCommandRules {
    long_commands: &[
        sqlfluffrs_types::client_commands::LongClientCommand { name: "delimiter", argument: sqlfluffrs_types::client_commands::ArgumentKind::Delimiter },
        sqlfluffrs_types::client_commands::LongClientCommand { name: "source", argument: sqlfluffrs_types::client_commands::ArgumentKind::FileName },
    ],
    short_commands: &[
        sqlfluffrs_types::client_commands::ShortClientCommand { text: "\\d", buffer_action: sqlfluffrs_types::client_commands::BufferAction::Keep, argument: Some(sqlfluffrs_types::client_commands::ArgumentKind::Delimiter) },
        sqlfluffrs_types::client_commands::ShortClientCommand { text: "\\.", buffer_action: sqlfluffrs_types::client_commands::BufferAction::Discard, argument: Some(sqlfluffrs_types::client_commands::ArgumentKind::FileName) },
        sqlfluffrs_types::client_commands::ShortClientCommand { text: "\\g", buffer_action: sqlfluffrs_types::client_commands::BufferAction::End, argument: None },
        sqlfluffrs_types::client_commands::ShortClientCommand { text: "\\G", buffer_action: sqlfluffrs_types::client_commands::BufferAction::End, argument: None },
    ],
    opaque_token_names: &["back_quote", "block_comment", "dollar_quote", "dollar_quote_opener", "double_quote", "inline_comment", "single_quote"],
    line_command_after_block_comment: true,
    dash_dash_comment_at_statement_start: false,
    collected_line_marker: Some("\\g"),
    default_delimiter: ";",
    max_delimiter_bytes: Some(15),
});


